import{_ as t,o as s,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"02 · 栈、队列与哈希表","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/dsa/02.md","filePath":"bagu/dsa/02.md"}'),e={name:"bagu/dsa/02.md"};function l(i,a,p,r,d,c){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="_02-·-栈、队列与哈希表" tabindex="-1">02 · 栈、队列与哈希表 <a class="header-anchor" href="#_02-·-栈、队列与哈希表" aria-label="Permalink to &quot;02 · 栈、队列与哈希表&quot;">​</a></h1><blockquote><p>栈和队列是&quot;受限的线性表&quot;，限制反而是它们的价值。哈希表是&quot;用空间换 O(1)&quot;的极致交易。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><ul><li><strong>栈</strong>：只在一端进出，所以&quot;后进先出&quot;——<strong>它天然适合处理&quot;嵌套&quot;和&quot;回溯&quot;</strong>。</li><li><strong>队列</strong>：一端进一端出，所以&quot;先进先出&quot;——<strong>它天然适合处理&quot;排队&quot;和&quot;逐层推进&quot;</strong>。</li><li><strong>哈希表</strong>：用哈希函数把 key 直接算成数组下标，跳过&quot;查找&quot;这个过程。</li></ul><h2 id="生活类比" tabindex="-1">生活类比 <a class="header-anchor" href="#生活类比" aria-label="Permalink to &quot;生活类比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结构</th><th>场景</th></tr></thead><tbody><tr><td>栈</td><td>一摞盘子：只能从最上面拿；浏览器后退（最近的先退）；Ctrl+Z</td></tr><tr><td>队列</td><td>排队买奶茶：先来先走；打印机任务队列</td></tr><tr><td>双端队列</td><td>地铁闸机双向都能过（两端都能进出）</td></tr><tr><td>优先队列</td><td>急诊分诊：不是先来先看，是最严重的先看（本质是堆）</td></tr><tr><td>哈希表</td><td>超市存包柜：凭号码直接开柜，不用一个个找</td></tr></tbody></table><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、栈-为什么-受限-反而有用" tabindex="-1">一、栈：为什么&quot;受限&quot;反而有用 <a class="header-anchor" href="#一、栈-为什么-受限-反而有用" aria-label="Permalink to &quot;一、栈：为什么&quot;受限&quot;反而有用&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        +-----+</span></span>
<span class="line"><span>        |  3  | &lt; top（只能从这里进出）</span></span>
<span class="line"><span>        +-----+</span></span>
<span class="line"><span>        |  2  |</span></span>
<span class="line"><span>        +-----+</span></span>
<span class="line"><span>        |  1  |</span></span>
<span class="line"><span>        +-----+</span></span></code></pre></div><p><strong>它解决的问题</strong>：<strong>任何&quot;最近的那个还没处理完，就来了新的&quot;场景</strong>。</p><table tabindex="0"><thead><tr><th>场景</th><th>为什么是栈</th></tr></thead><tbody><tr><td>函数调用</td><td>调 A 里调 B，B 返回后必须回到 A 的那一行 &gt; 用栈保存返回地址</td></tr><tr><td>括号匹配</td><td>遇到左括号压栈，右括号弹栈比对 &gt; 最近没闭合的先闭合</td></tr><tr><td>表达式求值</td><td>后缀表达式计算、中缀转后缀</td></tr><tr><td>撤销操作</td><td>最近的操作最先撤销</td></tr><tr><td>DFS</td><td>深度优先就是&quot;一条路走到黑，走不通退回上一步&quot;</td></tr><tr><td>浏览器后退</td><td>最近访问的先退</td></tr></tbody></table><p><strong>函数调用栈是理解&quot;递归&quot;的关键</strong>：每次递归都在栈上压一帧（参数、局部变量、返回地址）。递归太深会<strong>栈溢出</strong>，因为栈空间有限（通常 1~8MB）。</p><h3 id="二、队列-为什么-排队-需要专门的结构" tabindex="-1">二、队列：为什么&quot;排队&quot;需要专门的结构 <a class="header-anchor" href="#二、队列-为什么-排队-需要专门的结构" aria-label="Permalink to &quot;二、队列：为什么&quot;排队&quot;需要专门的结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     +---+---+---+---+</span></span>
<span class="line"><span>出 &lt; | 1 | 2 | 3 |   | &lt; 入</span></span>
<span class="line"><span>     +---+---+---+---+</span></span>
<span class="line"><span>      front        rear</span></span></code></pre></div><p><strong>用数组实现队列的坑</strong>：出队后 front 后移，前面空出来的位置浪费了。两种解法：</p><ol><li><strong>循环队列</strong>：<code>rear = (rear + 1) % capacity</code>，把数组当环用。</li><li><strong>链表实现</strong>：天然没有空间浪费。</li></ol><p><strong>循环队列的判空/判满</strong>（高频细节）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>保留一个空位：</span></span>
<span class="line"><span>  空：front == rear</span></span>
<span class="line"><span>  满：(rear + 1) % capacity == front</span></span>
<span class="line"><span>  &gt; 实际容量是 capacity - 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或者用 size 变量记录元素个数（更直观，推荐）</span></span></code></pre></div><p><strong>变体</strong>：</p><ul><li><strong>双端队列（Deque）</strong>：两端都能进出。滑动窗口最大值就用它。</li><li><strong>优先队列</strong>：出队顺序按优先级，不是按时间。<strong>实现是堆</strong>（见 03 篇）。</li><li><strong>阻塞队列</strong>：空了消费者等，满了生产者等——线程池、消息队列的基础。</li></ul><h3 id="三、哈希表-三个必须搞清的问题" tabindex="-1">三、哈希表：三个必须搞清的问题 <a class="header-anchor" href="#三、哈希表-三个必须搞清的问题" aria-label="Permalink to &quot;三、哈希表：三个必须搞清的问题&quot;">​</a></h3><h4 id="问题-1-哈希函数怎么设计" tabindex="-1">问题 1：哈希函数怎么设计 <a class="header-anchor" href="#问题-1-哈希函数怎么设计" aria-label="Permalink to &quot;问题 1：哈希函数怎么设计&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index = hash(key) % capacity</span></span></code></pre></div><p>要求：</p><ul><li><strong>计算快</strong>（不能比遍历还慢）</li><li><strong>分布均匀</strong>（减少冲突）</li><li><strong>相同 key 必须得到相同值</strong>（否则查不到）</li></ul><p><strong>工程优化</strong>：当 <code>capacity</code> 是 2 的幂时，<code>hash % capacity</code> 等价于 <code>hash &amp; (capacity - 1)</code>，位运算比取模快得多。这就是为什么 <code>HashMap</code> 的容量总是 2 的幂。</p><p>代价：2 的幂会让&quot;低位相同的 hash&quot;全部冲突，所以 <code>HashMap</code> 会把 hash 值再&quot;扰动&quot;一次（<code>h ^ (h &gt;&gt;&gt; 16)</code>，把高 16 位异或到低 16 位），让高位也参与运算。</p><h4 id="问题-2-冲突怎么解决" tabindex="-1">问题 2：冲突怎么解决 <a class="header-anchor" href="#问题-2-冲突怎么解决" aria-label="Permalink to &quot;问题 2：冲突怎么解决&quot;">​</a></h4><p><strong>方案 A：链地址法（拉链）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bucket[0] &gt; [k1,v1] &gt; [k3,v3] &gt; null</span></span>
<span class="line"><span>bucket[1] &gt; null</span></span>
<span class="line"><span>bucket[2] &gt; [k2,v2] &gt; null</span></span></code></pre></div><p>冲突的元素挂在同一个桶的链表上。<code>HashMap</code> 用这个。</p><p><strong>方案 B：开放寻址法</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>冲突了就往后找下一个空位：</span></span>
<span class="line"><span>  index, index+1, index+2, ...</span></span></code></pre></div><ul><li>优点：不用指针，缓存友好，空间紧凑。</li><li>缺点：删除麻烦（不能直接置空，要打&quot;墓碑&quot;标记）；装太满会性能骤降。</li></ul><p><code>ThreadLocalMap</code>（Java）、Python 的 dict 用这个思路。</p><h4 id="问题-3-扩容-rehash" tabindex="-1">问题 3：扩容（rehash） <a class="header-anchor" href="#问题-3-扩容-rehash" aria-label="Permalink to &quot;问题 3：扩容（rehash）&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>负载因子 = 元素数 / 桶数</span></span>
<span class="line"><span>HashMap 默认 0.75</span></span>
<span class="line"><span>  &gt; 超过就扩容为 2 倍，所有元素重新计算下标</span></span></code></pre></div><p><strong>为什么要有负载因子</strong>：装得太满 &gt; 冲突概率急剧上升 &gt; 链表变长 &gt; 查找退化。</p><p><strong>为什么是 0.75</strong>：权衡空间和时间。太小浪费空间，太大冲突多。0.75 是数学上（泊松分布）算出来的经验值。</p><p><strong>扩容为什么是 2 倍</strong>：因为容量是 2 的幂，扩容后每个元素要么<strong>留在原位</strong>，要么<strong>移动到&quot;原位 + 旧容量&quot;</strong>——不需要重新算哈希，只需看 hash 的一个新增位是 0 还是 1。这让 rehash 快很多。</p><p><strong>Java 8 的优化</strong>：链表长度 ≥ 8 且桶数 ≥ 64 时，链表转成<strong>红黑树</strong>，查找从 O(n) 变成 O(log n)。防止极端情况下（恶意构造的 hash 冲突）性能崩塌。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果没有栈-函数怎么返回" tabindex="-1">反事实 1：如果没有栈，函数怎么返回 <a class="header-anchor" href="#反事实-1-如果没有栈-函数怎么返回" aria-label="Permalink to &quot;反事实 1：如果没有栈，函数怎么返回&quot;">​</a></h3><p>每个函数调用都要记录&quot;返回到哪一行、局部变量是什么&quot;。没有栈的话：</p><ul><li>要么把这些存到堆里（要手动管理，极慢）</li><li>要么只支持一层调用（不可能）</li></ul><p>栈的&quot;后进先出&quot;恰好匹配&quot;函数调用的嵌套结构&quot;——<strong>最后被调用的函数最先返回</strong>。这不是巧合，是结构匹配。</p><h3 id="反事实-2-如果没有哈希表-查找要多久" tabindex="-1">反事实 2：如果没有哈希表，查找要多久 <a class="header-anchor" href="#反事实-2-如果没有哈希表-查找要多久" aria-label="Permalink to &quot;反事实 2：如果没有哈希表，查找要多久&quot;">​</a></h3><p>1000 万个 key，用数组或链表查一个：O(n)，平均 500 万次比较。 哈希表：算一次哈希 + 访问一次数组，O(1)。</p><p><strong>代价</strong>：需要额外 2~3 倍的空间（桶要留空位），且<strong>失去了顺序</strong>（无法范围查询、无法排序遍历）。这就是数据库索引不用哈希的原因。</p><h3 id="反事实-3-如果负载因子是-1-0" tabindex="-1">反事实 3：如果负载因子是 1.0 <a class="header-anchor" href="#反事实-3-如果负载因子是-1-0" aria-label="Permalink to &quot;反事实 3：如果负载因子是 1.0&quot;">​</a></h3><p>桶全满，冲突概率极高。理论上链地址法还能工作，但平均链表长度会飙升，查找退化成 O(n)。</p><p>极端例子：如果哈希函数很差（所有 key 都映射到同一个桶），哈希表直接退化成链表。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：栈和队列的区别？各用在什么场景？</strong></p><blockquote><p>区别在&quot;进出顺序&quot;：栈 LIFO，队列 FIFO。 场景要具体：栈用于函数调用、括号匹配、DFS、撤销；队列用于 BFS、任务调度、生产者消费者、消息队列。</p></blockquote><p><strong>Q：怎么用两个栈实现一个队列？</strong></p><blockquote><p>入队压入 <code>in</code> 栈；出队时如果 <code>out</code> 栈空，把 <code>in</code> 全部倒入 <code>out</code>，然后从 <code>out</code> 弹出。 <strong>关键点</strong>：每个元素最多被移动两次，所以<strong>摊销 O(1)</strong>。</p></blockquote><p><strong>Q：哈希表怎么解决冲突？</strong></p><blockquote><p>两种：链地址法（冲突挂链表，Java HashMap）和开放寻址法（往后找空位，ThreadLocalMap）。 <strong>加分</strong>：说清各自的优劣——拉链法删除简单但缓存不友好；开放寻址缓存友好但删除要打墓碑标记。</p></blockquote><p><strong>Q：HashMap 为什么容量是 2 的幂？</strong></p><blockquote><p>两个原因：① <code>hash &amp; (n-1)</code> 比 <code>hash % n</code> 快；② 扩容时元素只需判断&quot;留在原位还是移到原位+n&quot;，不用重算哈希。</p></blockquote><p><strong>Q：HashMap 为什么线程不安全？</strong></p><blockquote><p>三个典型问题：① 并发 put 可能覆盖彼此的数据；② JDK 7 的头插法在并发扩容时可能形成<strong>环形链表</strong>，导致 get 死循环；③ size 计数不准。 解法：<code>ConcurrentHashMap</code>（JDK 8 用 CAS + synchronized 锁单个桶）。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>哈希表查找为什么 O(1)？</span></span>
<span class="line"><span>  &gt; 怎么算下标？（hash % capacity）</span></span>
<span class="line"><span>    &gt; 冲突了怎么办？（拉链 / 开放寻址）</span></span>
<span class="line"><span>      &gt; 装太满会怎样？（冲突变多，退化成 O(n)）</span></span>
<span class="line"><span>        &gt; 怎么避免？（负载因子 + 扩容）</span></span>
<span class="line"><span>          &gt; 扩容为什么要重新分配？（容量变了，下标全变）</span></span>
<span class="line"><span>            &gt; 为什么容量取 2 的幂？（位运算 + 扩容只需判断一位）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/dsa/01">复杂度与数组、链表</a>：栈/队列/哈希表都可以用数组或链表实现，选型依据同 01 篇</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/03">树与堆</a>：优先队列的实现是堆；HashMap 冲突严重时转红黑树</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/dsa/04">图与并查集</a>：BFS 用队列，DFS 用栈（或递归）</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/01">索引与 B+ 树</a>：哈希索引只支持等值查询，就是因为哈希打散了顺序</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：阻塞队列是生产者-消费者模型的载体</li><li><strong>&gt; 影响</strong> 工程实践：Redis 的字典（渐进式 rehash）、LRU（哈希 + 双向链表）、消息队列</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么&quot;两个栈实现队列&quot;是摊销 O(1)？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为每个元素<strong>最多被移动两次</strong>：一次是从 <code>in</code> 倒入 <code>out</code>，一次是被弹出。</p><p>考虑 n 次操作（n 次入队 + n 次出队）：</p><ul><li>n 次入队：每次 O(1)，共 O(n)</li><li>出队：每次 <code>out</code> 空了才倒一次，总共倒 n 个元素，共 O(n)</li><li>总代价 O(n)，平均到 2n 次操作 &gt; <strong>摊销 O(1)</strong></li></ul><p>注意单次最坏情况仍是 O(n)（那一次要倒整个栈），但<strong>摊销</strong>是 O(1)。这和 <code>ArrayList</code> 扩容是同一类分析。</p></details><p><strong>Q2：哈希表的 O(1) 是最坏情况还是平均情况？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>平均情况</strong>。</p><p>最坏情况是 O(n)：所有 key 都冲突到同一个桶，退化成链表。</p><p>现实中能否发生：</p><ul><li>哈希函数差 &gt; 容易发生。</li><li>恶意攻击（哈希碰撞攻击）&gt; 攻击者构造大量同 hash 的参数，让服务器 CPU 打满。这是真实的 DoS 手法（2011 年多个语言受影响）。</li></ul><p>所以 Java 8 加了&quot;链表转红黑树&quot;（≥8 个转），把最坏情况从 O(n) 降到 O(log n)。</p><p>面试标准答法：<strong>&quot;平均 O(1)，最坏 O(n)；工程上通过好的哈希函数 + 扩容 + 红黑树把最坏情况兜住&quot;</strong>。</p></details><p><strong>Q3：为什么循环队列要&quot;牺牲一个位置&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为如果 <code>front == rear</code> 既可能表示&quot;空&quot;也可能表示&quot;满&quot;，无法区分。</p><p>两种解法：</p><ol><li><strong>牺牲一个位置</strong>：满的条件是 <code>(rear+1) % cap == front</code>，此时实际只能存 <code>cap-1</code> 个元素。</li><li><strong>加一个 size 变量</strong>：<code>size == 0</code> 是空，<code>size == cap</code> 是满。更直观，也不浪费空间，推荐。</li></ol><p>第三种（不推荐）：用标志位记录&quot;最后一次操作是入队还是出队&quot;，靠它区分空和满。逻辑绕，容易错。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;一摞盘子&quot;会让人以为栈只能存少量</strong>。栈的容量取决于实现，可以动态扩容（但函数调用栈通常是固定大小的，所以会溢出）。</li><li><strong>&quot;优先队列&quot;不是队列</strong>。它不保证 FIFO，只保证&quot;优先级最高的先出&quot;，底层是堆，不是链表。</li><li><strong>哈希表的&quot;O(1)&quot;忽略了哈希函数的开销</strong>。如果 key 是长字符串，算哈希本身是 O(长度)——所以缓存哈希值（Java 的 String 就缓存了 <code>hash</code>）。</li><li><strong><code>HashMap</code> 的遍历顺序不是插入顺序</strong>。要插入顺序用 <code>LinkedHashMap</code>，要排序用 <code>TreeMap</code>。</li><li><strong>开放寻址法删除不能直接置空</strong>。置空会切断后续元素的探测链，必须用&quot;墓碑&quot;标记。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出栈的 4 个典型应用场景，并解释&quot;为什么嵌套结构天然适合栈&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能写出循环队列的判空/判满条件，并解释为什么要&quot;牺牲一个位置&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说清哈希表冲突的两种解法，各举一个真实实现（HashMap / ThreadLocalMap）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释 HashMap 容量为什么是 2 的幂（要说出两个理由）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释负载因子 0.75 的意义，以及扩容为什么是 2 倍</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能用&quot;摊销分析&quot;讲清&quot;两个栈实现队列&quot;的复杂度</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能说出哈希表 O(1) 是平均而非最坏，以及 Java 8 怎么兜住最坏情况</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,78)])])}const g=t(e,[["render",l]]);export{u as __pageData,g as default};
